INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Netzwerksicherheit immer durch Firewalls allein gewährleistet wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Mehrere Maßnahmen nötig"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Netzwerksicherheit für ein IT-System plane?', 3, '[{"text": "Bedrohungserkennung", "correct": true, "because": "Schützt vor Angriffen"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Sicherheit zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen gehören zur Netzwerksicherheit?', 5, '[{"text": "Firewalls", "correct": true, "because": "Filtern Datenverkehr"}, {"text": "Verschlüsselung", "correct": true, "because": "Schützt Daten"}, {"text": "Büromöbel", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Netzwerksicherheit schützt vor unbefugtem Zugriff. b) Sie ist immer kostenlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten entstehen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Netzwerksicherheit für ein IT-System plane?', 4, '[{"text": "Firewall-Regeln", "correct": false, "because": "Schützen Netzwerk"}, {"text": "Verschlüsselung", "correct": false, "because": "Sichert Daten"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Netzwerksicherheit nur physische Bedrohungen abwehrt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Cyber-Bedrohungen"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Netzwerksicherheit?', 3, '[{"text": "Datenschutz", "correct": true, "because": "Sichert Informationen"}, {"text": "Schnellste Installation", "correct": false, "because": "Sicherheit zählt"}, {"text": "Weniger Schutz", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken sind bei Netzwerksicherheit entscheidend?', 5, '[{"text": "Intrusion Detection", "correct": true, "because": "Erkennt Angriffe"}, {"text": "VPN", "correct": true, "because": "Sichert Verbindungen"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Netzwerksicherheit nutzt Verschlüsselung. b) Sie ist immer unzuverlässig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kann zuverlässig sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Netzwerksicherheit zu gewährleisten?', 4, '[{"text": "Firewalls", "correct": false, "because": "Schützen Netzwerk"}, {"text": "Antivirus-Software", "correct": false, "because": "Erkennt Bedrohungen"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Netzwerksicherheit immer kostenlos?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten entstehen"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Netzwerksicherheit?', 4, '[{"text": "Datenschutz", "correct": true, "because": "Sichert Informationen"}, {"text": "Verhinderung von Angriffen", "correct": true, "because": "Schützt System"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Netzwerksicherheit nur für große Netzwerke relevant ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Netzwerke"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Netzwerksicherheit effektiv umzusetzen?', 3, '[{"text": "Verschlüsselung", "correct": true, "because": "Sichert Daten"}, {"text": "Günstigste Lösung", "correct": false, "because": "Sicherheit wichtiger"}, {"text": "Bunte Optik", "correct": false, "because": "Irrelevant"}]'),
