('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Netzwerksicherheit?', 5, '[{"text": "Bedrohungserkennung", "correct": true, "because": "Schützt vor Angriffen"}, {"text": "Zugriffskontrolle", "correct": true, "because": "Regelt Berechtigungen"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Netzwerksicherheit plane?', 3, '[{"text": "Verschlüsselung", "correct": false, "because": "Sichert Daten"}, {"text": "Firewall", "correct": false, "because": "Schützt Netzwerk"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Netzwerksicherheit nur für drahtlose Netzwerke relevant?', 3, '[{"text": "Nein", "correct": true, "because": "Auch kabelgebunden"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
